/**
 * @method
 * @name writeXFORMEditor
 * @description desc
 * @param {string} id desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.writeXFORMEditor = function(id) {
    try {
        document.write('<OBJECT ID="' + id + '" style="WIDTH: 100%; HEIGHT: 100%" CLASSID="clsid:051F7EA4-D912-4997-9FA8-27816B24E3E8" >');
        document.write('<param name="WebServerURL" value="https://10.10.3.28:8083">');
        document.write('<PARAM NAME="BaseURL" VALUE="/submission/">');
        document.write('<PARAM NAME="LayoutURL" VALUE="editor.do">');
        document.write('<PARAM NAME="DataURL" VALUE="editor.do">');
        document.write('<PARAM NAME="CmtURL" VALUE="editor.do">');
        document.write('<PARAM NAME="TimeConnect" VALUE="20">');
        document.write('<PARAM NAME="TimeReceive" VALUE="20">');
        document.write('<PARAM NAME="TimeDataReceive" VALUE="20">');
        document.write('<PARAM NAME="NATION" VALUE="KOR">');
        document.write('</OBJECT>');
    } catch (E) {
        alert(E);
    }
};
